<?php
declare(strict_types=1);
function fleet_controller_otp_key(bool $create=false): string {
    $root=realpath(dirname(__DIR__));$dir=realpath(dirname(GOOGLE_CREDENTIALS_FILE));if(!$root||!$dir||!is_writable($dir)||str_starts_with(strtolower(rtrim($dir,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR),strtolower(rtrim($root,DIRECTORY_SEPARATOR).DIRECTORY_SEPARATOR)))throw new RuntimeException('App Controller OTP secure storage is unavailable.');$path=$dir.'/fleet-controller-otp.key';if(!is_file($path)){if(!$create)throw new RuntimeException('OTP encryption key is unavailable.');if(file_put_contents($path,random_bytes(32),LOCK_EX)!==32)throw new RuntimeException('Could not create the OTP encryption key.');@chmod($path,0600);} $key=file_get_contents($path);if(!is_string($key)||strlen($key)!==32)throw new RuntimeException('OTP encryption key is invalid.');return $key;
}
function fleet_controller_otp_encrypt(int $userId,string $secret): string {$iv=random_bytes(12);$tag='';$cipher=openssl_encrypt($secret,'aes-256-gcm',fleet_controller_otp_key(true),OPENSSL_RAW_DATA,$iv,$tag,'fleet-controller-totp-v1:'.$userId);if(!is_string($cipher))throw new RuntimeException('Could not encrypt the App Controller OTP secret.');return json_encode(['iv'=>base64_encode($iv),'tag'=>base64_encode($tag),'ciphertext'=>base64_encode($cipher)],JSON_THROW_ON_ERROR);}
function fleet_controller_otp_decrypt(int $userId,string $box): string {$v=json_decode($box,true);if(!is_array($v))throw new RuntimeException('Saved OTP secret is malformed.');$iv=base64_decode((string)($v['iv']??''),true);$tag=base64_decode((string)($v['tag']??''),true);$cipher=base64_decode((string)($v['ciphertext']??''),true);if($iv===false||$tag===false||$cipher===false)throw new RuntimeException('Saved OTP secret is malformed.');$secret=openssl_decrypt($cipher,'aes-256-gcm',fleet_controller_otp_key(),OPENSSL_RAW_DATA,$iv,$tag,'fleet-controller-totp-v1:'.$userId);if(!is_string($secret))throw new RuntimeException('Saved OTP secret could not be decrypted.');return $secret;}
function fleet_totp_base32_encode(string $bytes): string {$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$bits='';foreach(str_split($bytes) as $c)$bits.=str_pad(decbin(ord($c)),8,'0',STR_PAD_LEFT);$out='';foreach(str_split($bits,5) as $chunk)$out.=$alphabet[bindec(str_pad($chunk,5,'0'))];return $out;}
function fleet_totp_base32_decode(string $text): string {$alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';$text=strtoupper(rtrim($text,'='));$bits='';foreach(str_split($text) as $c){$n=strpos($alphabet,$c);if($n===false)throw new InvalidArgumentException('OTP secret is invalid.');$bits.=str_pad(decbin($n),5,'0',STR_PAD_LEFT);}$out='';foreach(str_split($bits,8) as $chunk){if(strlen($chunk)===8)$out.=chr(bindec($chunk));}return $out;}
function fleet_totp_code(string $secret,int $counter): string {$key=fleet_totp_base32_decode($secret);$msg=pack('N2',intdiv($counter,4294967296),$counter%4294967296);$hash=hash_hmac('sha1',$msg,$key,true);$offset=ord($hash[19])&15;$binary=((ord($hash[$offset])&127)<<24)|((ord($hash[$offset+1])&255)<<16)|((ord($hash[$offset+2])&255)<<8)|(ord($hash[$offset+3])&255);return str_pad((string)($binary%1000000),6,'0',STR_PAD_LEFT);}
function fleet_totp_match(string $secret,string $code,int $now=null): ?int {$code=preg_replace('/\s+/','',trim($code));if(!preg_match('/^\d{6}$/',$code))return null;$counter=(int)floor(($now??time())/30);for($n=$counter-1;$n<=$counter+1;$n++)if(hash_equals(fleet_totp_code($secret,$n),$code))return $n;return null;}
